import assert from 'node:assert/strict';
import {randomUUID,createHash} from 'node:crypto';
import {readFileSync,writeFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
const root=process.cwd();
const {withDisposablePostgres}=await import(pathToFileURL(root+'/scripts/helpers/disposable-postgres.mjs'));
const {preparePhase3Database,as,json,literal}=await import(pathToFileURL(root+'/scripts/helpers/v2-phase3-fixture.mjs'));
const report={scope:'Local disposable PostgreSQL; real repository routines with synthetic auth/storage and fixture-granted entitlements. No browser, provider or hosted acceptance.',checks:[],status:'running'};
const check=(id,fn)=>{fn();report.checks.push({id,status:'pass'});console.log('PASS '+id)};
try{await withDisposablePostgres(async db=>{
 const {query,rejects}=db,f=preparePhase3Database(db),admin=f.admin;
 for(const m of ['20261113090000_add_v2_sales_catalogue.sql','20261113100000_add_v2_checkout_ledger.sql','20261113110000_add_v2_payment_fulfillment.sql'])db.apply(m);
 const rpc=(id,name,args='')=>JSON.parse(query(as(id,`select public.${name}(${args})`))||'null');
 const user=(product=null)=>{const id=randomUUID();query(`insert into auth.users(id,email) values('${id}','${id}@example.invalid');update public.profiles set role='student',is_active=true where id='${id}'`);if(product){const q=JSON.parse(query(`select public.quote_v2_products(array['${product}'])`));query(`select public.grant_v2_purchase('${id}',array['${product}'],'synthetic:${id}',now()-interval '1 second','${q.price_version_id}',${q.amount_paise},'INR')`)}return id};
 const s=user('quant_crash'),unpaid=user(),wrong=user('di_crash'),other=user('quant_crash');
 const b=f.batch('quant',true);
 const course=(id=s)=>rpc(id,'get_my_v2_published_course',`'${b.id}'`),state=(id=s)=>rpc(id,'get_my_v2_learning_state',`'${b.id}'`),meeting=(id=s)=>rpc(id,'get_my_v2_meeting',`'${b.id}','${b.eventKey}'`),schedule=(id=s)=>rpc(id,'get_my_v2_batch_schedules');
 const enroll=(id,active=true,revision=0)=>rpc(admin,'set_v2_batch_enrollment',`'${b.id}','${id}',${active},${revision}`);
 const register=(id=s,active=true,revision=0)=>rpc(admin,'set_v2_live_registration',`'${b.id}','${id}',${active},${revision}`);
 const deny=(sql,pattern)=>rejects(as(admin,sql),pattern);
 check('draft-enrollment-remains-hidden',()=>{enroll(s);assert.equal(course(),null);assert.equal(meeting(),null);assert.equal(schedule().length,0)});
 check('draft-live-registration-denied',()=>deny(`select public.set_v2_live_registration('${b.id}','${s}',true,0)`,/Published live batch required/));
 check('meeting-draft-before-publication',()=>rpc(admin,'save_v2_meeting_draft',json({batchId:b.id,batchRevision:1,expectedRevision:0,requestId:randomUUID(),links:[{key:b.eventKey,url:'https://meet.google.com/abc-defg-hij'}]})));
 f.publish(b);
 check('published-recording-access-without-live',()=>{assert.equal(course().sessions.length,1);assert.equal(state().liveRegistered,false);assert.equal(schedule()[0].events.length,0);assert.equal(meeting(),null)});
 check('wrong-or-missing-entitlement-and-no-enrollment-denied',()=>{for(const id of [unpaid,wrong,other,admin,null]){assert.equal(course(id),null);assert.equal(meeting(id),null)}});
 check('registration-requires-current-access-and-enrollment',()=>{for(const id of [unpaid,wrong,other])deny(`select public.set_v2_live_registration('${b.id}','${id}',true,0)`,/product access and enrollment/)});
 check('enrollment-stale-revision-conflicts',()=>query(as(admin,`do $$begin perform public.set_v2_batch_enrollment('${b.id}','${s}',false,0);raise exception 'missing conflict';exception when sqlstate 'PT409' then null;end;$$`)));

 check('registered-student-sees-live-schedule-and-private-meeting',()=>{register();assert.equal(state().liveRegistered,true);assert.equal(schedule()[0].events.length,1);assert.equal(meeting().url,'https://meet.google.com/abc-defg-hij');assert.equal(meeting(other),null)});
 check('course-and-schedule-never-contain-private-meeting-url',()=>{assert.doesNotMatch(JSON.stringify([course(),schedule(),state()]),/meet\.google|actor_id|request_id/)});
 check('stale-registration-cannot-reinstate-access',()=>{register(s,false,1);assert.equal(meeting(),null);query(as(admin,`do $$begin perform public.set_v2_live_registration('${b.id}','${s}',true,1);raise exception 'missing conflict';exception when sqlstate 'PT409' then null;end;$$`));assert.equal(meeting(),null);register(s,true,2);assert.ok(meeting())});
 check('registration-audit-matches-three-confirmed-transitions',()=>assert.equal(query(`select count(*) from public.v2_live_registration_audit where batch_id='${b.id}' and student_id='${s}'`),'3'));
 rpc(admin,'set_v2_live_session_mapping',`'${b.id}','${b.eventKey}','${b.sessionKey}',1`);
 check('unpublished-meeting-edit-stays-private',()=>{rpc(admin,'save_v2_meeting_draft',json({batchId:b.id,batchRevision:1,expectedRevision:1,requestId:randomUUID(),links:[{key:b.eventKey,url:'https://meet.google.com/klm-nopq-rst'}]}));assert.equal(meeting().url,'https://meet.google.com/abc-defg-hij')});
 f.publish(b,1);
 check('republish-delivers-exact-reviewed-meeting',()=>assert.equal(meeting().url,'https://meet.google.com/klm-nopq-rst'));
 check('republish-requires-mapping-reconfirmation',()=>{const rows=rpc(admin,'list_v2_live_session_mappings',`'${b.id}'`);assert.equal(rows.length,1);assert.equal(rows[0].publicationRevision,1)});
 check('completion-requires-explicit-session-mapping',()=>deny(`select public.complete_v2_learning_live_class('${b.id}','${b.eventKey}',2)`,/mapping is required/));
 rpc(admin,'set_v2_live_session_mapping',`'${b.id}','${b.eventKey}','${b.sessionKey}',2`);
 check('stale-completion-is-denied-before-write',()=>deny(`select public.complete_v2_learning_live_class('${b.id}','${b.eventKey}',1)`,/Publication changed/));
 check('completion-creates-feedback-and-removes-join',()=>{rpc(admin,'complete_v2_learning_live_class',`'${b.id}','${b.eventKey}',2`);assert.equal(state().obligations.length,1);assert.equal(meeting(),null);assert.equal(course().sessions.length,1)});
 check('completion-replay-does-not-duplicate-obligation',()=>{const r=rpc(admin,'complete_v2_learning_live_class',`'${b.id}','${b.eventKey}',2`);assert.equal(r.replayed,true);assert.equal(state().obligations.length,1)});
 check('missed-class-feedback-resolves-without-invented-attendance',()=>{const o=state().obligations[0];rpc(s,'submit_v2_session_feedback',`'${o.id}','${randomUUID()}',${json({attendance:'missed',usefulness:null,clarity:null,comment:''})}`);assert.equal(state().obligations.length,0);assert.equal(query(`select response->>'attendance' from public.v2_session_feedback where student_id='${s}'`),'missed')});
 check('withdraw-enrollment-immediately-denies-readers',()=>{enroll(s,false,1);assert.equal(course(),null);assert.equal(state(),null);assert.equal(meeting(),null);assert.equal(schedule().length,0);enroll(s,true,2);assert.ok(course())});
 f.publish(b,2,'unpublish');
 check('unpublish-denies-all-readers-without-revoking-purchase',()=>{assert.equal(course(),null);assert.equal(state(),null);assert.equal(meeting(),null);assert.equal(schedule().length,0);assert.equal(query(`select public.v2_student_has_product('${s}','quant')`),'t')});
 f.publish(b,3);
 check('republish-restores-course-with-completed-class-still-closed',()=>{assert.ok(course());assert.equal(state().obligations.length,0);assert.equal(meeting(),null)});
 check('inactive-student-or-revoked-purchase-denies-all-readers',()=>{for(const mutation of [`update public.profiles set is_active=false where id='${s}'`,`update public.v2_purchases set revoked_at=now() where student_id='${s}'`]){const r=JSON.parse(query(`begin;${mutation};set local role authenticated;set local request.jwt.claim.sub='${s}';select jsonb_build_array(public.get_my_v2_published_course('${b.id}'),public.get_my_v2_learning_state('${b.id}'),public.get_my_v2_meeting('${b.id}','${b.eventKey}'),public.get_my_v2_batch_schedules());rollback;`));assert.deepEqual(r,[null,null,null,[]])}});
 check('student-cannot-toggle-own-registration',()=>rejects(as(s,`select public.set_v2_live_registration('${b.id}','${s}',false,3)`),/Admin access required/));

 const empty={...b,id:randomUUID(),templateId:randomUUID(),eventKey:randomUUID()};
 const doc={...b.document,sessions:[],events:[{...b.document.events[0],key:empty.eventKey}]};
 rpc(admin,'save_v2_template_draft',`'${empty.templateId}','quant',0,'${randomUUID()}',${json(doc)}`);
 const request={id:empty.id,templateId:empty.templateId,templateRevision:1,expectedRevision:0,requestId:randomUUID(),title:'Synthetic live-only batch',startDate:'2027-01-10',timeZone:'Asia/Kolkata',events:null};
 const preview=rpc(admin,'preview_v2_batch_draft',json(request));rpc(admin,'save_v2_batch_draft',`${json(request)},${literal(preview.fingerprint)}`);
 rpc(admin,'save_v2_meeting_draft',json({batchId:empty.id,batchRevision:1,expectedRevision:0,requestId:randomUUID(),links:[{key:empty.eventKey,url:'https://meet.google.com/abc-defg-hij'}]}));f.publish(empty);
 rpc(admin,'set_v2_batch_enrollment',`'${empty.id}','${s}',true,0`);rpc(admin,'set_v2_live_registration',`'${empty.id}','${s}',true,0`);
 check('live-only-batch-can-publish-enroll-and-join',()=>{assert.ok(rpc(s,'get_my_v2_meeting',`'${empty.id}','${empty.eventKey}'`));assert.equal(rpc(s,'get_my_v2_published_course',`'${empty.id}'`).sessions.length,0)});
 check('confirmed-defect-live-only-completion-has-no-valid-session',()=>{deny(`select public.set_v2_live_session_mapping('${empty.id}','${empty.eventKey}','${b.sessionKey}',1)`,/published session in the live class subject/);deny(`select public.complete_v2_learning_live_class('${empty.id}','${empty.eventKey}',1)`,/mapping is required/);assert.equal(query(`select count(*) from public.v2_live_class_completions where batch_id='${empty.id}'`),'0')});
 report.findings=[{id:'DELIVERY-01',severity:'high',status:'reproduced',description:'The live-only creation path publishes a joinable batch with zero sessions. Learning-enabled completion requires a same-subject published session, so the completion UI has no selectable mapping and completion cannot succeed.'},{id:'DELIVERY-02',severity:'medium',status:'confirmed-behavior',description:'Republishing a meeting-only edit invalidates the current publication mapping; Admin must reconfirm mapping before completion.'}];
});report.status='passed'}catch(e){report.status='failed';report.error=e.message;console.error(e);process.exitCode=1}finally{report.sourceSha256=createHash('sha256').update(readFileSync(new URL(import.meta.url))).digest('hex');writeFileSync('/tmp/ace-admin-delivery-evidence.json',JSON.stringify(report,null,2)+'\n')}
